import{_ as e,o as n,c as a,a2 as o}from"./chunks/framework.KobcctIO.js";const u=JSON.parse('{"title":"Gens-Horizon: Cloud Engine Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/horizon/overview.md","filePath":"guide/horizon/overview.md"}'),i={name:"guide/horizon/overview.md"};function t(l,s,r,p,c,d){return n(),a("div",null,[...s[0]||(s[0]=[o(`<h1 id="gens-horizon-cloud-engine-architecture" tabindex="-1">Gens-Horizon: Cloud Engine Architecture <a class="header-anchor" href="#gens-horizon-cloud-engine-architecture" aria-label="Permalink to &quot;Gens-Horizon: Cloud Engine Architecture&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Engine-Headless%20CLI-blue.svg" alt="Engine"><img src="https://img.shields.io/badge/Protocol-IPC%20JSON%20Stream-green.svg" alt="Protocol"><img src="https://img.shields.io/badge/Storage-Provider%20Agnostic-orange.svg" alt="Storage"></div><p><strong>Gens-Horizon</strong> (<code>C:\\dev\\Gens-Horizon</code>) is the standalone headless cloud synchronization engine of the Gens ecosystem. Designed to run in the background as a child process of Gens-Launcher, it orchestrates bidirectional synchronization, delta versioning, and disaster recovery across major cloud storage providers (Google Drive, Dropbox, OneDrive).</p><hr><h2 id="_1-core-purpose-and-philosophy" tabindex="-1">1. Core Purpose and Philosophy <a class="header-anchor" href="#_1-core-purpose-and-philosophy" aria-label="Permalink to &quot;1. Core Purpose and Philosophy&quot;">​</a></h2><p>Traditional Minecraft launchers usually back up instances by compressing an entire 500 MB directory into a single monolithic zip and uploading it to a server. This approach wastes massive bandwidth, introduces sluggish wait times, and rapidly exhausts storage quotas.</p><p>Gens-Horizon replaces this model with:</p><ul><li><strong>Delta Sync Technology:</strong> Only altered blocks and files are compressed and transferred.</li><li><strong>Headless Isolation:</strong> The engine runs decoupled from the GUI and can execute as a standalone CLI or compiled native binary (<code>pkg</code>).</li><li><strong>Provider Agnostic Design:</strong> Extensible Factory pattern supporting diverse storage providers.</li><li><strong>Resilience and Concurrency Safety:</strong> Atomic lockfiles and active heartbeats protect instances from concurrent writes and corrupted states.</li></ul><hr><h2 id="_2-component-topology" tabindex="-1">2. Component Topology <a class="header-anchor" href="#_2-component-topology" aria-label="Permalink to &quot;2. Component Topology&quot;">​</a></h2><p>The internal architecture of Gens-Horizon is organized around focused modules:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                                  [ CLI / Launcher IPC ]</span></span>
<span class="line"><span>                                             |</span></span>
<span class="line"><span>                                             v</span></span>
<span class="line"><span>                                        index.js</span></span>
<span class="line"><span>                                             |</span></span>
<span class="line"><span>         +-----------------+-----------------+-----------------+</span></span>
<span class="line"><span>         |                 |                 |                 |</span></span>
<span class="line"><span>         v                 v                 v                 v</span></span>
<span class="line"><span>      check.js          sync.js          upload.js        rollback.js</span></span>
<span class="line"><span>         |                 |                 |                 |</span></span>
<span class="line"><span>         +-----------------+--------+--------+-----------------+</span></span>
<span class="line"><span>                                    |</span></span>
<span class="line"><span>                                    v</span></span>
<span class="line"><span>                            scanner.js (SHA-256)</span></span>
<span class="line"><span>                                    |</span></span>
<span class="line"><span>                                    v</span></span>
<span class="line"><span>                           provider.js (Factory)</span></span>
<span class="line"><span>                     /              |              \\</span></span>
<span class="line"><span>                    v               v               v</span></span>
<span class="line"><span>             providers/google  providers/dropbox  providers/onedrive</span></span>
<span class="line"><span>                                    |</span></span>
<span class="line"><span>        +---------------------------+---------------------------+</span></span>
<span class="line"><span>        |                           |                           |</span></span>
<span class="line"><span>        v                           v                           v</span></span>
<span class="line"><span>     lock.js                     Auth.js               cloud-operations.js</span></span>
<span class="line"><span>  (Atomic Locks)           (PBKDF2 / AES-GCM)        (Index &amp; Cleanup)</span></span></code></pre></div><ul><li><strong><code>index.js</code></strong>: Main CLI entry point. Intercepts standard loggers (<code>console.log</code>, <code>console.warn</code>) to redirect library text to <code>process.stderr</code>, preserving clean JSON on <code>process.stdout</code>.</li><li><strong><code>scanner.js</code></strong>: High-performance local file scanner. Computes SHA-256 digests while enforcing concurrency limits (<code>withConcurrency</code>) to prevent file descriptor exhaustion (<code>EMFILE</code>).</li><li><strong><code>upload.js</code></strong>: Analyzes differences against the last known local manifest, builds a targeted delta bundle, and uploads it.</li><li><strong><code>sync.js</code></strong>: Queries the remote manifest index, downloads missing deltas in chronological sequence, and applies them locally.</li><li><strong><code>cloud-operations.js</code></strong>: Centralizes remote index retrieval and purges obsolete or duplicate cloud backups (<code>getCloudIndexAndCleanDuplicates</code>).</li><li><strong><code>rollback.js</code></strong>: Reconstructs previous instance states deterministically to restore any historical snapshot.</li><li><strong><code>zip-utils.js</code></strong>: High-efficiency in-memory zip decompression using <code>yauzl</code>, with Path Traversal defenses and zip header verification (<code>0x504B0304</code>).</li></ul><hr><h2 id="_3-ipc-json-communication-protocol" tabindex="-1">3. IPC JSON Communication Protocol <a class="header-anchor" href="#_3-ipc-json-communication-protocol" aria-label="Permalink to &quot;3. IPC JSON Communication Protocol&quot;">​</a></h2><p>Gens-Horizon communicates with the parent launcher over standard <code>stdout</code> and <code>stdin</code> streams. Messages on <code>stdout</code> are strictly formatted as single-line JSON objects:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PROGRESS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;step&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;COMPRESSING&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">65</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;instance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Survival_Folia&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="supported-event-types" tabindex="-1">Supported Event Types: <a class="header-anchor" href="#supported-event-types" aria-label="Permalink to &quot;Supported Event Types:&quot;">​</a></h3><ul><li><code>PROGRESS</code>: Real-time phase reporting (<code>SCANNING</code>, <code>COMPRESSING</code>, <code>UPLOADING</code>, <code>APPLYING_DELTA</code>).</li><li><code>INFO</code>: Informational text messages.</li><li><code>SUCCESS</code>: Operation completion with metadata summary.</li><li><code>ERROR</code>: Typed error payloads.</li><li><code>ROLLBACK_LIST</code>: Chronological enumeration of available restore points.</li><li><code>CHECK_RESULT</code>: Comparison between local and remote state.</li><li><code>CLOUD_LIST</code>: Full inventory of synchronized instances.</li></ul>`,19)])])}const g=e(i,[["render",t]]);export{u as __pageData,g as default};
